"""Compile text markers against every decoded vocabulary piece, including BPE merges."""


def compile_markers(tokenizer, start, close, end):
    # Opening is anchored at the first generated byte; closing is a substring.
    opening = len(start)
    states = opening + len(close)
    done, dead = states, states + 1

    def step(state, text):
        for char in text:
            if state >= states:
                break
            if state < opening:
                state = state + 1 if char == start[state] else dead
            else:
                prefix = close[: state - opening] + char
                if prefix.endswith(close):
                    state = done
                else:
                    state = opening + max(
                        (n for n in range(len(close)) if prefix.endswith(close[:n])),
                        default=0,
                    )
        return state

    default = tuple(dead if state < opening else opening for state in range(states))
    classes = {default: 0}
    exceptions = []
    vocabulary = tokenizer.get_vocab()
    for token in sorted(set(vocabulary.values())):
        text = tokenizer.decode([token], skip_special_tokens=False)
        transitions = tuple(step(state, text) for state in range(states))
        kind = classes.setdefault(transitions, len(classes))
        if kind:
            exceptions.append((token << 8) | kind)
    if (
        states > 64
        or len(classes) > 256
        or any(token >> 24 for token in vocabulary.values())
    ):
        raise ValueError("thinking marker automaton exceeds its state or token limit")
    matrix = [0] * ((states * len(classes) + 3) // 4)
    for transitions, kind in classes.items():
        for state, target in enumerate(transitions):
            index = state * len(classes) + kind
            matrix[index // 4] |= target << (8 * (index % 4))
    words = [states, len(classes), opening, done, dead, 0, len(exceptions), 0]
    words += matrix
    offsets = len(words)
    words += [0] * states
    for state in range(opening, states):
        suffix = (
            tuple(end)
            if state == opening
            else tuple(
                tokenizer.encode(close[state - opening :], add_special_tokens=False)
            )
        )
        if not suffix or len(suffix) > 64:
            raise ValueError("thinking marker suffix exceeds its token limit")
        words[offsets + state] = len(words)
        words += [len(suffix), *suffix]
    words[7] = len(words)
    words += exceptions
    if len(words) > 1024:
        raise ValueError("thinking marker automaton exceeds 4096 bytes")
    return tuple(words)
